import { describe, expect, it } from "vitest";
import { getNetworkDemoLabel, getInvoiceFooterLabel } from "./network";

describe("Network Aware Footer & Invoice Labels", () => {
  it("omits testnet demo text when network is PUBLIC (mainnet)", () => {
    expect(getNetworkDemoLabel("PUBLIC")).toBe("");
    expect(getInvoiceFooterLabel("GABCD...1234", "PUBLIC")).toBe(
      "Generated by PayLoop · GABCD...1234"
    );
    expect(getInvoiceFooterLabel("GABCD...1234", "PUBLIC")).not.toContain("testnet");
  });

  it("includes testnet demo text when network is TESTNET", () => {
    expect(getNetworkDemoLabel("TESTNET")).toBe("Testnet demo");
    expect(getInvoiceFooterLabel("GABCD...1234", "TESTNET")).toBe(
      "Generated by PayLoop · Stellar testnet demo · GABCD...1234"
    );
  });

  it("handles fallback to TESTNET or custom dev networks", () => {
    expect(getNetworkDemoLabel("LOCAL")).toBe("Testnet demo");
    expect(getInvoiceFooterLabel("GABCD...1234", "FUTURENET")).toContain(
      "Stellar testnet demo"
    );
  });
});
